from itertools import combinations
U = set('ABCDEFG')
F = [(set('A'), set('BCEF')), (set('E'), set('DG')), (set('BC'), set('A'))]
def closure(X):
    X = set(X)
    while True:
        new = set(X)
        for l, r in F:
            if l <= new: new |= r
        if new == X: return X
        X = new
for s in ['A', 'BC', 'E', 'B', 'C']:
    print(s + '+ =', ''.join(sorted(closure(s))))
keys = []
for k in range(1, 8):
    for c in combinations(sorted(U), k):
        if closure(c) == U and not any(set(x) <= set(c) for x in keys):
            keys.append(''.join(c))
print('candidate keys:', keys)
viol = [(''.join(sorted(l)), ''.join(sorted(r))) for l, r in F if not (r <= l) and closure(l) != U]
print('BCNF violations (LHS not a superkey):', viol)
print('A only key:', keys == ['A'], '| B:', sorted(keys) == ['A', 'BC'],
      '| C:', sorted(keys) == ['A', 'BC', 'E'], '| D (not BCNF):', bool(viol))
